library(shiny)
library(sfsmisc)

source("texts.R")

# Plot colors; the dark values follow the book's color map (darkmode/darkmode.md, section 6)
pal <- list(light = c(bg = "white", fg = "black", nsl = "grey50", rej = "red"),
            dark  = c(bg = "#222222", fg = "#FFFFFF", nsl = "#737373", rej = "#FF3F30"))

sig <- 10

K <- 50

M <- 1000

spd <- 10

pw <- function(mu, sigma, n, a) {
  q <- qt(1 - a / 2, n - 1)
  d <- mu * sqrt(n) / sigma
  pt(-q, n - 1, d) + pt(q, n - 1, d, lower.tail = FALSE)
}

fill <- function(t, v) {
  for (k in names(v)) t <- gsub(paste0("{", k, "}"), v[[k]], t, fixed = TRUE)
  t
}

# Trials in which the test got it wrong
wr <- function(x, a) if (x$h0) x$p <= a else x$p > a

# ---- Quiz ----

# What changes: the key of each row for an increase (a reversed change swaps up and down); NA: not asked
ckey <- rbind(
  fp  = c(n = "same", alpha = "up",   bonf = "down", eff = NA,     tests = "same"),
  fn  = c(n = "down", alpha = "down", bonf = "up",   eff = "down", tests = "same"),
  fwe = c(n = NA,     alpha = NA,     bonf = "down", eff = NA,     tests = "up"),
  sd  = c(n = "same", alpha = NA,     bonf = NA,     eff = "same", tests = NA),
  se  = c(n = "down", alpha = "same", bonf = NA,     eff = "same", tests = NA),
  w   = c(n = "down", alpha = "down", bonf = NA,     eff = "same", tests = NA),
  sh  = c(n = "down", alpha = NA,     bonf = NA,     eff = NA,     tests = NA),
  p   = c(n = NA,     alpha = "same", bonf = NA,     eff = NA,     tests = NA),
  avg = c(n = "same", alpha = "same", bonf = NA,     eff = "up",   tests = NA))

# The five questions: a change and its two rows
qz <- list(sd = c("n", "sd", "se"), err = c("n", "fp", "fn"), alpha = c("alpha", "fp", "fn"),
           p = c("alpha", "p", "w"), eff = c("eff", "fn", "se"))

cells <- names(qz)

# Changes with several tests
cmt <- c("bonf", "tests")

swp <- c(up = "down", down = "up", same = "same")

qchg <- function(id) {
  ch <- qz[[id]][1]
  rs <- qz[[id]][-1]
  rv <- ch %in% c("n", "alpha", "eff") && runif(1) < 0.5
  v <- switch(ch,
    n     = { z <- sort(sample(c(10, 20, 30, 50, 100, 200), 2)); list(n1 = z[1 + rv], n2 = z[2 - rv]) },
    alpha = { z <- sort(sample(c(0.01, 0.05, 0.1), 2)); list(a1 = sprintf("%.2f", z[1 + rv]), a2 = sprintf("%.2f", z[2 - rv])) },
    eff   = list(),
    { k <- sample(c(3, 5, 10), 1); list(k = k, f0 = sprintf("%.1f", 100 * (1 - 0.95^k)), f1 = sprintf("%.1f", 100 * (1 - (1 - 0.05 / k)^k))) })
  d <- if (rv) "down" else "up"
  key <- ckey[rs, ch]
  if (rv) key <- swp[key]
  lb <- vapply(rs, function(x) paste0(qs$chg$row[[x]], if (ch %in% cmt && x %in% c("fp", "fn")) qs$chg$each else ""), "")
  why <- vapply(rs, function(x) fill(qs$chg$why[[ch]][[x]], v), "")
  mis <- lapply(rs, function(x) {
    m <- qs$chg$mis[[ch]][[x]]
    if (!length(m)) return(m)
    if (rv) names(m) <- swp[names(m)]
    vapply(m, fill, "", v)
  })
  list(id = id, rows = unname(rs), lab = unname(lb), key = unname(key), why = unname(why), mis = mis,
       text = fill(if (ch == "eff") qs$chg$qeff[[d]] else fill(qs$chg$q, list(chg = fill(qs$chg$chg[[ch]][[d]], v))),
                   list(note = qs$chg$note)))
}

qck <- function(q, a) {
  a <- strsplit(paste0(a, ","), ",", fixed = TRUE)[[1]][seq_along(q$rows)]
  if (anyNA(a) || !all(a %in% names(swp))) return(NA)
  if (all(a == q$key)) "ok" else "no"
}

qfb <- function(q, a) {
  a <- strsplit(a, ",", fixed = TRUE)[[1]]
  li <- vapply(seq_along(q$rows), function(i) {
    ok <- a[i] == q$key[i]
    m <- if (!ok && a[i] %in% names(q$mis[[i]])) paste0(q$mis[[i]][[a[i]]], " ") else ""
    paste0("<li>", fill(qs$chg$fb[[if (ok) "ok" else "no"]],
                        list(row = q$lab[i], key = qs$chg$opt[[q$key[i]]], mis = m, why = q$why[i])), "</li>")
  }, "")
  ok <- all(a == q$key)
  list(col = if (ok) "blue" else "red",
       html = paste0(fill(qs$fb[[if (ok) "ok" else "no"]], list(r = sum(a == q$key), m = length(q$rows))),
                     "<ul>", paste(li, collapse = ""), "</ul>"))
}

# The answer grid: one row of radio buttons (up, down, same) per quantity; a: the given answers, if any
qgrid <- function(q, a = NULL) {
  a <- if (length(a)) strsplit(a, ",", fixed = TRUE)[[1]]
  o <- names(swp)
  tags$table(id = "gr", class = "table table-condensed",
    tags$thead(tags$tr(tags$th(""), lapply(o, function(x) tags$th(qs$chg$opt[[x]])), if (length(a)) tags$th(""))),
    tags$tbody(lapply(seq_along(q$rows), function(i) tags$tr(
      tags$td(HTML(q$lab[i])),
      lapply(o, function(x) tags$td(tags$label(
        `aria-label` = paste0(gsub("<[^>]+>|\\\\[()]?", "", q$lab[i]), ": ", qs$chg$opt[[x]]),
        tags$input(type = "radio", name = paste0("gr", i), value = x, checked = if (length(a) && a[i] == x) NA)))),
      if (length(a)) tags$td(if (a[i] == q$key[i]) span(class = "ok", "✓") else span(class = "no", "✗"))))))
}

# The background of the intervals, which the browser draws on top (drw() in the JavaScript)
pci <- function(h0, eff, p) {
  par(mar = c(4, 1, 1.6, 1) + 0.1)
  plot(NA, xlim = c(-26, 12), ylim = c(K + 0.5, 0.5), axes = FALSE, xlab = "Change in blood pressure (mmHg)", ylab = "")
  abline(v = 0, lty = 3)
  mtext(expression(H[0]), 3, 0.4, at = 0, adj = 0)
  if (!h0) {
    abline(v = -eff, lwd = 2, col = p[["nsl"]])
    mtext(expression("True" ~ mu), 3, 0.4, at = -eff, adj = 1, col = p[["nsl"]])
  }
  eaxis(1)
  list(plt = par("plt"), usr = par("usr"))
}

# The fixed example under "What am I looking at?"
pwh <- function(p) {
  n <- 30
  m <- -7
  y <- m + sig * as.vector(scale(qnorm(ppoints(n))))
  q <- qt(0.975, n - 1) * sig / sqrt(n)
  b <- 1.7
  v <- b + 1.3 * ((seq_along(y) * 0.618034) %% 1 - 0.5)
  par(mar = c(4, 1, 1.6, 1) + 0.1)
  plot(NA, xlim = c(-30, 15), ylim = c(-0.15, 2.45), axes = FALSE, xlab = "Change in blood pressure (mmHg)", ylab = "")
  abline(v = 0, lty = 3)
  mtext(expression(H[0]), 3, 0.4, at = 0, adj = 0)
  eaxis(1)
  points(y, v, pch = 16, col = p[["nsl"]])
  segments(m - q, b, m + q, b, lwd = 2.5, col = p[["fg"]])
  points(m, b, pch = 16, cex = 1.8, col = p[["fg"]])
  d <- strwidth("M")
  x <- par("usr")[1] + d
  tx <- x + 1.4 * d
  points(x, 0.75, pch = 16, cex = 1.8, col = p[["fg"]])
  text(tx, 0.75, "Sample mean", adj = 0)
  segments(x - 0.8 * d, 0.4, x + 0.8 * d, 0.4, lwd = 2.5, col = p[["fg"]])
  text(tx, 0.4, "95% confidence interval", adj = 0)
  points(x, 0.05, pch = 16, col = p[["nsl"]])
  text(tx, 0.05, "Observations", adj = 0)
}

